// V3 procedural cinematic atmosphere: layered circuitry, traveling pulses and scan beams.
(function createAtmosphere(){
 const canvas=document.createElement('canvas');canvas.id='cyberAtmosphere';canvas.setAttribute('aria-hidden','true');
 const shade=document.getElementById('shade');(shade?.parentNode||document.body).insertBefore(canvas,shade?.nextSibling||null);
 const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)return;
 let w=0,h=0,dpr=1,paths=[],particles=[],frame=0,raf=0,visible=true;
 const mobile=()=>innerWidth<760;
 function resize(){dpr=Math.min(devicePixelRatio||1,1.5);w=innerWidth;h=innerHeight;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);canvas.style.width=w+'px';canvas.style.height=h+'px';ctx.setTransform(dpr,0,0,dpr,0,0);
 const count=mobile()?17:34;paths=Array.from({length:count},(_,i)=>{const x=Math.random()*w,y=Math.random()*h;const len=65+Math.random()*200;const dir=Math.random()<.5?1:-1;return {points:[[x,y],[x+dir*len*.45,y],[x+dir*len*.65,y+(i%2?1:-1)*30],[x+dir*len,y+(i%2?1:-1)*30]],speed:.00012+Math.random()*.0003,phase:Math.random(),width:.8+Math.random()*1.6};});particles=Array.from({length:mobile()?36:95},()=>({x:Math.random()*w,y:Math.random()*h,r:.5+Math.random()*2,s:.12+Math.random()*.45,p:Math.random()*6.28}));}
 function draw(t){if(!visible)return;frame++;ctx.clearRect(0,0,w,h);const python=document.body.classList.contains('python');const col=python?'255,208,103':'73,227,255';
 // animated luminous scan lines
 const scan=(t*.035)%(h+260)-130;const gradient=ctx.createLinearGradient(0,scan-110,0,scan+110);gradient.addColorStop(0,'rgba('+col+',0)');gradient.addColorStop(.5,'rgba('+col+',.085)');gradient.addColorStop(1,'rgba('+col+',0)');ctx.fillStyle=gradient;ctx.fillRect(0,scan-110,w,220);
 paths.forEach((p,i)=>{ctx.beginPath();p.points.forEach(([x,y],j)=>j?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.lineWidth=p.width;ctx.strokeStyle='rgba('+col+','+(0.16+Math.sin(t*.0006+i)*.08)+')';ctx.stroke();const progress=(t*p.speed+p.phase)%1;const lengths=[];let total=0;for(let j=1;j<p.points.length;j++){const a=p.points[j-1],b=p.points[j],dist=Math.hypot(b[0]-a[0],b[1]-a[1]);lengths.push(dist);total+=dist}let pos=progress*total;for(let j=0;j<lengths.length;j++){if(pos<=lengths[j]){const a=p.points[j],b=p.points[j+1],v=pos/lengths[j];const x=a[0]+(b[0]-a[0])*v,y=a[1]+(b[1]-a[1])*v;ctx.beginPath();ctx.arc(x,y,2.5,0,Math.PI*2);ctx.fillStyle='rgba('+col+',.95)';ctx.shadowBlur=19;ctx.shadowColor='rgba('+col+',.95)';ctx.fill();ctx.shadowBlur=0;break}pos-=lengths[j]}});
 particles.forEach(p=>{p.y-=p.s;if(p.y<-5)p.y=h+5;ctx.beginPath();ctx.arc(p.x+Math.sin(t*.0005+p.p)*13,p.y,p.r,0,Math.PI*2);ctx.fillStyle='rgba('+col+','+(.18+.26*(.5+.5*Math.sin(t*.001+p.p)))+')';ctx.fill()});
 raf=requestAnimationFrame(draw)}
 resize();window.addEventListener('resize',resize,{passive:true});document.addEventListener('visibilitychange',()=>{visible=!document.hidden;if(visible)raf=requestAnimationFrame(draw);else cancelAnimationFrame(raf)});
 const mq=matchMedia('(prefers-reduced-motion: reduce)');if(!mq.matches)raf=requestAnimationFrame(draw);else canvas.style.display='none';
})();


